CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE request_status AS ENUM ('NEW','TRIAGE','INSPECTION_REQUIRED','QUOTE_PENDING','APPROVAL_PENDING','SCHEDULED','IN_PROGRESS','AWAITING_ACCEPTANCE','COMPLETED','CANCELLED','REJECTED','DELAYED','AWAITING_PARTS','DISPUTED');
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), auth_subject TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, phone_e164 TEXT, email TEXT, preferred_locale TEXT NOT NULL DEFAULT 'ar-SA', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, organization_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE memberships (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), organization_id UUID NOT NULL REFERENCES organizations(id), role TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(user_id,organization_id,role));
CREATE TABLE properties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id UUID REFERENCES users(id), managing_organization_id UUID REFERENCES organizations(id), name TEXT NOT NULL, property_type TEXT NOT NULL, address_line TEXT NOT NULL, city TEXT NOT NULL, region TEXT, latitude NUMERIC(9,6), longitude NUMERIC(9,6), access_notes_private TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE property_units (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), property_id UUID NOT NULL REFERENCES properties(id), unit_code TEXT NOT NULL, unit_type TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', UNIQUE(property_id,unit_code));
CREATE TABLE property_access (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), property_id UUID NOT NULL REFERENCES properties(id), unit_id UUID REFERENCES property_units(id), user_id UUID NOT NULL REFERENCES users(id), can_create_requests BOOLEAN NOT NULL DEFAULT FALSE, can_view_costs BOOLEAN NOT NULL DEFAULT FALSE, can_approve_quotes BOOLEAN NOT NULL DEFAULT FALSE, approval_limit_sar NUMERIC(12,2), valid_from TIMESTAMPTZ NOT NULL DEFAULT now(), valid_until TIMESTAMPTZ, granted_by UUID REFERENCES users(id));
CREATE TABLE service_categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT UNIQUE NOT NULL, name_ar TEXT NOT NULL, name_en TEXT, requires_inspection BOOLEAN NOT NULL DEFAULT FALSE, requires_qualified_provider BOOLEAN NOT NULL DEFAULT TRUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE providers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id), display_name TEXT NOT NULL, provider_kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING_REVIEW', service_area_description TEXT, average_rating NUMERIC(3,2), completed_jobs INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE provider_services (provider_id UUID NOT NULL REFERENCES providers(id), category_id UUID NOT NULL REFERENCES service_categories(id), qualification_status TEXT NOT NULL DEFAULT 'PENDING', valid_until DATE, PRIMARY KEY(provider_id,category_id));
CREATE TABLE maintenance_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_number BIGSERIAL UNIQUE, created_by UUID NOT NULL REFERENCES users(id), property_id UUID NOT NULL REFERENCES properties(id), unit_id UUID REFERENCES property_units(id), category_id UUID NOT NULL REFERENCES service_categories(id), title TEXT NOT NULL, description TEXT NOT NULL, status request_status NOT NULL DEFAULT 'NEW', priority TEXT NOT NULL DEFAULT 'NORMAL', preferred_at TIMESTAMPTZ, triage_risk_level TEXT, triage_notes_internal TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE request_assignments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES maintenance_requests(id), provider_id UUID NOT NULL REFERENCES providers(id), offered_at TIMESTAMPTZ NOT NULL DEFAULT now(), response_deadline TIMESTAMPTZ, responded_at TIMESTAMPTZ, response TEXT, decline_reason TEXT, assigned_by UUID REFERENCES users(id), assignment_score NUMERIC(6,3), override_reason TEXT);
CREATE TABLE quotes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES maintenance_requests(id), provider_id UUID REFERENCES providers(id), version INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', labor_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (labor_amount >= 0), materials_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (materials_amount >= 0), visit_fee NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (visit_fee >= 0), discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0), tax_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0), total_amount NUMERIC(12,2) NOT NULL CHECK (total_amount >= 0), currency CHAR(3) NOT NULL DEFAULT 'SAR', assumptions TEXT, exclusions TEXT, warranty_days INTEGER, valid_until TIMESTAMPTZ, approved_at TIMESTAMPTZ, approved_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(request_id,version));
CREATE TABLE quote_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), quote_id UUID NOT NULL REFERENCES quotes(id) ON DELETE CASCADE, item_type TEXT NOT NULL, description TEXT NOT NULL, quantity NUMERIC(12,3) NOT NULL CHECK (quantity > 0), unit TEXT, unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0), line_total NUMERIC(12,2) NOT NULL CHECK (line_total >= 0));
CREATE TABLE suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING_REVIEW', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE supplier_products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID NOT NULL REFERENCES suppliers(id), sku TEXT, name_ar TEXT NOT NULL, specification JSONB NOT NULL DEFAULT '{}'::jsonb, unit TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE supplier_offers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES supplier_products(id), price NUMERIC(12,2) NOT NULL CHECK (price >= 0), currency CHAR(3) NOT NULL DEFAULT 'SAR', availability_status TEXT NOT NULL, stock_quantity NUMERIC(12,3), delivery_fee NUMERIC(12,2) NOT NULL DEFAULT 0, verified_at TIMESTAMPTZ, valid_until TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE work_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES maintenance_requests(id), created_by UUID NOT NULL REFERENCES users(id), log_type TEXT NOT NULL, description TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE file_assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), uploaded_by UUID NOT NULL REFERENCES users(id), storage_key TEXT UNIQUE NOT NULL, original_filename TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0), scan_status TEXT NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE request_files (request_id UUID NOT NULL REFERENCES maintenance_requests(id), file_id UUID NOT NULL REFERENCES file_assets(id), purpose TEXT NOT NULL, PRIMARY KEY(request_id,file_id));
CREATE TABLE customer_acceptances (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES maintenance_requests(id), accepted_by UUID NOT NULL REFERENCES users(id), outcome TEXT NOT NULL, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES maintenance_requests(id), invoice_number TEXT UNIQUE NOT NULL, status TEXT NOT NULL, subtotal NUMERIC(12,2) NOT NULL, tax_amount NUMERIC(12,2) NOT NULL DEFAULT 0, total_amount NUMERIC(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'SAR', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE complaints (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL REFERENCES maintenance_requests(id), created_by UUID NOT NULL REFERENCES users(id), category TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id UUID REFERENCES users(id), organization_id UUID REFERENCES organizations(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id UUID, reason TEXT, metadata_redacted JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_requests_status_created ON maintenance_requests(status,created_at DESC);
CREATE INDEX idx_requests_property_created ON maintenance_requests(property_id,created_at DESC);
CREATE INDEX idx_audit_entity ON audit_events(entity_type,entity_id,created_at DESC);
